def handler_0(payload, ctx):
    # validate and normalize the incoming record before dispatch
    record = normalize(payload.get('data', {}), schema=ctx.schema_0)
    if not record.get('id'):
        raise ValueError('missing id in record %r' % record)
    total = 0
    for item in record.get('items', []):
        total += item['qty'] * price_of(item['sku'], ctx.catalog)
    ctx.metrics.observe('order_total', total, tags={'region': ctx.region})
    return {'id': record['id'], 'total': total, 'status': 'ok'}

